sys_script_include.script:
//Part of MSSOTIQUBE-2578
var HSBC_Migration_Logs_Trace = Class.create();
HSBC_Migration_Logs_Trace.prototype = {
    initialize: function() {},
    log: function(batchID, isSummary, params) {
        try {
            var gr = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_migration_logs_trace');
            gr.initialize();
            gr.batch_id = batchID;
            gr.is_summary_row = isSummary;

            if (isSummary) {
                gr.total_records = params.totalRecords;
                gr.error_count = params.errorCount;
                gr.start_time = params.startTime;
                gr.end_time = params.endTime;
                gr.initiated_by = params.initiatedBy;
                gr.error_message = params.errorMessage;
				gr.schedule = params.schedule;

            } else {
                gr.record_sys_id = params.recordSysId;
                gr.record_status = params.status;
                gr.error_message = params.errorMessage;
                gr.migrated_on = new GlideDateTime();
                gr.source_table = params.sourceTable;
                gr.target_table = params.targetTable;
				gr.schedule = params.schedule;

            }
            gr.insert();
        } catch (error) {
            gs.error('HSBC_Migration_Logs_Trace Error: ' + error);
        }
    },
    type: 'HSBC_Migration_Logs_Trace'
};
